 void file(bool writing,bool bank){using namespace juce;auto folder=File::getSpecialLocation(File::userDocumentsDirectory).getChildFile("Nexum/Arpeggiator");folder.createDirectory();chooser=std::make_unique<FileChooser>(writing?(bank?"Save arp bank":"Save arp pattern"):(bank?"Load arp bank":"Load arp pattern"),folder,bank?"*.nxarpbank":"*.nxarp");auto safe=Component::SafePointer<ArpEditor>(this);auto document=ArpDocument::capture(p,bank?-1:slot);int target=slot;chooser->launchAsync((writing?FileBrowserComponent::saveMode|FileBrowserComponent::warnAboutOverwriting:FileBrowserComponent::openMode)|FileBrowserComponent::canSelectFiles,[safe,writing,bank,document,target](const FileChooser& fc){if(!safe)return;auto f=fc.getResult();if(f==File())return;Result result=Result::ok();if(writing){auto xml=document.createXml();if(!xml||!xml->writeTo(f.withFileExtension(bank?"nxarpbank":"nxarp")))result=Result::fail("Could not save arp file.");}else if(f.getSize()>8*1024*1024)result=Result::fail("Arp file is too large.");else {auto xml=XmlDocument::parse(f);result=xml?ArpDocument::apply(safe->p,ValueTree::fromXml(*xml),target):Result::fail("Invalid arp file.");}if(result.failed())AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Arpeggiator",result.getErrorMessage());safe->observe();safe->setSlot(juce::jlimit(0,11,(int)safe->p.value("seqArpSlot")));});}
